const htmlRaw = $json.data ?? $json.body ?? $json;
const html = typeof htmlRaw === "string"
  ? htmlRaw
  : JSON.stringify(htmlRaw);

// Localiza as linhas da tabela
const linhas = html.match(/<tr\b[^>]*>[\s\S]*?<\/tr>/gi) ?? [];

function limparHTML(valor) {
  return valor
    .replace(/<[^>]*>/g, "")
    .replace(/&nbsp;/gi, " ")
    .replace(/&amp;/gi, "&")
    .replace(/&lt;/gi, "<")
    .replace(/&gt;/gi, ">")
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .trim();
}

const clientes = linhas
  .map(linha => {
    const colunas = [
      ...linha.matchAll(/<t[dh]\b[^>]*>([\s\S]*?)<\/t[dh]>/gi)
    ].map(coluna => limparHTML(coluna[1]));

    if (colunas.length !== 4) return null;

    // Ignora o cabeçalho da tabela
    if (colunas[0].toLowerCase() === "nome") return null;

    const [nome, email, saldoTexto, perfil] = colunas;

    const saldo = Number(
      saldoTexto.replace(/[^\d,.-]/g, "").replace(/\./g, "").replace(",", ".")
    ) || 0;

    return {
      nome,
      email,
      saldo,
      perfil
    };
  })
  .filter(Boolean);

return [
  {
    json: {
      clientes
    }
  }
];

const entrada = $json.body ?? $json.data ?? $json;

// Aceita tanto um objeto quanto uma string JSON
const dados = typeof entrada === "string"
  ? JSON.parse(entrada)
  : entrada;

// Seu arquivo utiliza a chave "clintes"
const clientes = dados.clientes ?? dados.clintes ?? [];

const investimentosPorPerfil = {
  Conservador: [
    "Tesouro Selic",
    "CDB com liquidez diária",
    "LCI/LCA"
  ],
  Moderado: [
    "CDB",
    "Tesouro IPCA+",
    "Fundos de renda fixa",
    "Fundos imobiliários"
  ],
  Arrojado: [
    "Ações",
    "ETFs de ações",
    "Fundos imobiliários",
    "Fundos multimercado"
  ]
};

const resultado = clientes.map(cliente => {
  const perfil = String(cliente.perfil ?? "").trim();

  return {
    ...cliente,
    tiposInvestimento: investimentosPorPerfil[perfil] ?? [],
    perfilEncontrado: Boolean(investimentosPorPerfil[perfil])
  };
});

return resultado.map(cliente => ({
  json: cliente
}));
